 const codes=['en','es','fr','zh','ar','tr'], original=new WeakMap(), originalAttributes=new WeakMap();
 const notices={es:'Traducción preliminar; algunas explicaciones siguen en inglés. Revisión humana pendiente.',fr:'Traduction préliminaire ; certaines explications restent en anglais. Révision humaine en attente.',zh:'翻译预览；部分说明仍为英语，尚待人工审核。',ar:'معاينة ترجمة؛ بعض الشروحات بالإنجليزية. المراجعة البشرية قيد الانتظار.',tr:'Çeviri önizlemesi; bazı açıklamalar İngilizcedir. İnsan incelemesi bekleniyor.'};
 function translate(value,language='en'){
  const index=Math.max(0,codes.indexOf(language)),text=String(value);if(index===0)return text;
  const row=rows.find(r=>r[0]===text)||rows.find(r=>r[0].toLowerCase()===text.toLowerCase());
  if(row)return row[index];
  if(text.includes(' · '))return text.split(' · ').map(part=>translate(part,language)).join(' · ');
  const duration=text.match(/^(\d+(?:\.\d+)?) seconds \((estimated|timed|video)\)$/);if(duration)return translate(duration[1]+' seconds',language)+' ('+translate(duration[2],language)+')';
  const patterns=[[/^(\d+) days$/,'{0} days'],[/^(\d+) day$/,'{0} day'],[/^revision (\d+)$/,'revision {0}'],[/^(\d+(?:\.\d+)?) seconds$/,'{0} seconds'],[/^Question (\d+) of (\d+)$/,'Question {0} of {1}'],[/^(\d+) observed$/,'{0} observed'],[/^(\d+) matching entries$/,'{0} matching entries'],[/^(\d+) records$/,'{0} records'],[/^(\d+) episode entries$/,'{0} episode entries'],[/^(\d+) episode entry$/,'{0} episode entry']];
  for(const [pattern,key] of patterns){const match=text.match(pattern);if(match)return translate(key,language).replace(/\{(\d+)\}/g,(_,n)=>match[Number(n)+1]);}
  return text;
 }
 function date(value,language='en',options={year:'numeric',month:'short',day:'numeric'}){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return value;
  const [y,m,d]=value.split('-').map(Number);return new Intl.DateTimeFormat(codes.includes(language)?language:'en',options).format(new Date(y,m-1,d));
 }
 function apply(language='en'){
  const index=Math.max(0,codes.indexOf(language));document.title=translate('OpenFHS · Practice diary',language);document.documentElement.lang=codes[index];document.documentElement.dir=language==='ar'?'rtl':'ltr';
  document.querySelectorAll('p,h1,h2,h3,legend,label,summary,button,small').forEach(el=>{el.dir='auto';el.lang='en';});
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
  while(node=walker.nextNode()){if(node.parentElement.closest('script,style,textarea,pre,#active-cat,#avatar-preview,.profile-avatar,#sidebar-cat strong,.video-record h3,.video-privacy-form h3,[data-user-content]'))continue;const previous=original.get(node),current=node.textContent;const old=previous&&current===previous.translated?previous.source:current;const trimmed=old.trim();const translated=old.replace(trimmed,translate(trimmed,language));original.set(node,{source:old,translated});node.textContent=translated;if(translated!==old||index===0)node.parentElement.lang=codes[index];}
  document.querySelectorAll('[data-local-date]').forEach(el=>{el.textContent=date(el.dataset.localDate,language);});
  document.querySelectorAll('[aria-label],[placeholder]').forEach(el=>{let saved=originalAttributes.get(el)||{};for(const key of ['aria-label','placeholder']){if(!el.hasAttribute(key))continue;const current=el.getAttribute(key),prior=saved[key],source=prior&&current===prior.translated?prior.source:current,translated=translate(source,language);saved[key]={source,translated};el.setAttribute(key,translated);}originalAttributes.set(el,saved);});
  let banner=document.querySelector('#language-notice');if(!banner){banner=document.createElement('p');banner.id='language-notice';banner.className='callout';document.querySelector('main').prepend(banner);}banner.hidden=index===0;banner.textContent=notices[language]||'';
 }
 function hasTranslation(value,language){const index=codes.indexOf(language);return index>=0&&rows.some(row=>row[0].toLowerCase()===String(value).toLowerCase()&&typeof row[index]==='string'&&row[index].trim());}
 rows.push(...[["Breezy park","Parque con brisa","Parc au vent doux","微风公园","حديقة بنسيم","Esintili park"],["Pixel arcade (8-bit)","Salón arcade (8 bits)","Arcade pixelisée (8 bits)","像素街机（8位）","صالة البكسل (8 بت)","Piksel oyun salonu (8 bit)"],["Time difference from UTC (optional)","Diferencia horaria con UTC (opcional)","Décalage par rapport à UTC (facultatif)","与UTC的时差（可选）","فرق التوقيت عن UTC (اختياري)","UTC ile saat farkı (isteğe bağlı)"],["Leave blank if unsure","Deja en blanco si no lo sabes","Laissez vide en cas de doute","不确定请留空","اتركه فارغًا إن لم تكن متأكدًا","Emin değilseniz boş bırakın"],["Add a fictional cat","Añadir un gato ficticio","Ajouter un chat fictif","添加虚构猫咪","أضف قطًا خياليًا","Kurgusal bir kedi ekle"],["You can skip this. It means how far the local clock was ahead of or behind UTC when the episode happened. For example, MDT is -06:00 and MST is -07:00. Leave it blank if unsure; the app will not guess.","Puedes omitirlo. Indica cuánto adelantaba o atrasaba la hora local respecto a UTC durante el episodio. Por ejemplo, MDT es -06:00 y MST es -07:00. Si no lo sabes, déjalo en blanco; la aplicación no lo deducirá.","Vous pouvez passer cette question. Il s’agit de l’avance ou du retard de l’heure locale sur UTC lors de l’épisode. Par exemple, MDT correspond à -06:00 et MST à -07:00. En cas de doute, laissez vide ; l’application ne devinera pas.","此项可以跳过。它表示发作时当地时间比UTC早或晚多少。例如，MDT为-06:00，MST为-07:00。不确定请留空；应用不会猜测。","يمكنك تخطي هذا. يعني مقدار تقدم أو تأخر الساعة المحلية عن UTC وقت النوبة. مثلًا، MDT هو -06:00 وMST هو -07:00. اتركه فارغًا إن لم تكن متأكدًا؛ لن يخمّن التطبيق.","Bunu atlayabilirsiniz. Olay sırasında yerel saatin UTC’den ne kadar ileride veya geride olduğunu belirtir. Örneğin MDT -06:00, MST -07:00’dır. Emin değilseniz boş bırakın; uygulama tahminde bulunmaz."]]);
